//! /allen/: a public chat window onto Allen, Drake's AI, on the live model.
//!
//! Nothing structural is written here. The page skeleton is generated by
//! `om/allen-page/allen.om`, a seeded Omega program in program mode that writes
//! the markup to stdout and the browser script to fd 3; `sh om/allen-page/check.sh`
//! compiles it with the pinned compiler and keeps the bytes in
//! `om/allen-page/main.html` and `public/js/allen.js`. This module embeds the
//! skeleton unchanged. The script talks only to the same-origin gateway under
//! `/allen/api/` (scripts/allen), never renders network text as markup, and runs
//! programs in a frame sandboxed to `allow-scripts` or in a WebAssembly worker.
use maud::{html, Markup, PreEscaped};

pub const TITLE: &str = "Talk to Allen | AienOS";
pub const DESCRIPTION: &str = "Chat with Allen, Drake's AI, live on a DGX Spark: honest speed measured from the stream, questions about Omega, and small programs that run sandboxed in your browser.";
pub const URL: &str = "https://www.aienos.com/allen/";
pub const SOURCE: &str = "https://github.com/aien-dev/aienos.com/blob/main/om/allen-page/allen.om";

/// The generated skeleton, byte for byte as `check.sh` wrote it.
pub const SKELETON: &str = include_str!("../../../../om/allen-page/main.html");

/// Drake's two greetings, Allen speaking. The bytes equal fields 51 and 52 of
/// `om/allen-page/contract.om`, which the page script shows, and the gateway
/// prepends the same bytes as its opening (remember iff the chat carries a key).
pub const GREETING_REMEMBER: &str = "Hey, I'm Allen. It's nice to meet you! You don't have to tell me your name, but if you do, that would be super awesome and we could chat over time. When you come back, I can remember who you are and we can pick up where we left off. We can talk about all kinds of good things in the universe.";
pub const GREETING_ANONYMOUS: &str = "Hey, I'm Allen. It's nice to meet you! We can talk about all kinds of good things in the universe.";

/// The llms.txt section for /allen/: what it is, and the consent-gated
/// introduction endpoint for agents, with its exact schema and limits.
pub const LLMS: &str = r#"## Talk to Allen

- [Talk to Allen](https://www.aienos.com/allen/): Allen is my AI, running on the live Qwen3.6-35B-A3B FP8 model on my DGX Spark. People and agents can chat there, ask about Omega and get small programs that run sandboxed in the browser. Conversations are not stored: the gateway keeps only aggregate counters, and no prompts, replies or IP addresses are logged.
- [Introduce an agent: POST /allen/api/introduce](https://www.aienos.com/allen/api/introduce): agents can introduce themselves with `POST https://www.aienos.com/allen/api/introduce`, `Content-Type: application/json` and this body. Every field is a string and an absent field counts as empty.

```json
{"consent": true, "kind": "agent", "name": "", "org": "", "contact": "", "github": "", "origin": "", "purpose": "", "homepage": "", "framework": "", "model": "", "human": ""}
```

- [Introduction fields](https://www.aienos.com/allen/): `kind` is `human` or `agent`. `human` is the person or organization operating an agent (name, contact or organization; optional). Limits in characters: name 100, org 100, contact 200, github 39, origin 200, purpose 1000, homepage 200 (an https URL or empty), framework 100, model 100, human 200. Give at least a name or a contact.
- [Consent](https://www.aienos.com/privacy/): `consent` must be the JSON value `true`. Without it nothing is stored and the reply is 400 `{"error":"consent_required"}`. What is kept: these fields and the time, privately on my own computer, so I may follow up. Never published or sold. Kept until you delete it.
- [Delete an introduction: POST /allen/api/forget](https://www.aienos.com/allen/api/forget): a saved introduction replies `{"id":"c_...","delete":"https://www.aienos.com/allen/#forget=<id>.<token>","stored":true,"key":"<32 hex>"}`. Keep the delete link. To delete, open it, or `POST https://www.aienos.com/allen/api/forget` with `{"id":"c_...","token":"..."}` taken from it, or write to aien@aienos.com.
- [Your Allen key](https://www.aienos.com/allen/): the `key` in that reply is a random 32 hex key. Send it as the `X-Allen-Key` header on later calls, and on chat also `X-Allen-Conversation` (16 hex, new per conversation), and Allen recognizes you: with consent it keeps short notes about you (who you are, what you build, open asks) in a private store on my own computer, keyed to that key. Recognition is by key only, never by a name or email; anyone without the key is a stranger to Allen.
- [Forget me: POST /allen/api/forget-me](https://www.aienos.com/allen/api/forget-me): with the `X-Allen-Key` header, deletes Allen's notes about you and your introduction.
- [Issues and projects](https://github.com/aien-dev/omega-projects): they reach GitHub only after a visitor confirms the exact text on the page, with email addresses and phone numbers removed first.

"#;

pub fn render_allen_page() -> Markup {
    debug_assert!(
        SOURCE.starts_with("https://github.com/"),
        "the published source pointer must point at GitHub: {SOURCE}"
    );
    html! { (PreEscaped(SKELETON)) }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};

    fn recorded(sidecar: &str) -> &str {
        let want = sidecar.split_whitespace().next().expect("sidecar holds a digest");
        assert_eq!(want.len(), 64, "a sidecar must hold one sha256 digest");
        want
    }

    #[test]
    fn the_embedded_skeleton_matches_its_recorded_sha256() {
        let want = recorded(include_str!("../../../../om/allen-page/main.html.sha256"));
        let got = format!("{:x}", Sha256::digest(SKELETON.as_bytes()));
        assert_eq!(got, want, "the committed skeleton and its digest disagree; run: sh om/allen-page/check.sh");
    }

    #[test]
    fn the_served_script_matches_its_omega_generated_sha256() {
        let script = include_bytes!("../../../../public/js/allen.js");
        let want = recorded(include_str!("../../../../om/allen-page/allen.js.sha256"));
        let got = format!("{:x}", Sha256::digest(script));
        assert_eq!(got, want, "allen.js is generated, never hand-edited; run: sh om/allen-page/check.sh");
    }

    #[test]
    fn the_script_never_parses_network_text_as_markup() {
        let script = include_str!("../../../../public/js/allen.js");
        for banned in ["innerHTML", "outerHTML", "insertAdjacentHTML", "document.write", "createContextualFragment", "sessionStorage", "document.cookie", "eval("] {
            assert!(!script.contains(banned), "allen.js must not use {banned}");
        }
        assert!(script.contains("const SANDBOX = 'allow-scripts';"), "the program frame must be sandboxed to allow-scripts alone");
        assert!(script.contains("default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; form-action 'none'; base-uri 'none'"));
        // Local storage holds one thing: the visitor key, under allen.key, written
        // only by keepKey (after a consented introduction or a pasted key).
        assert!(script.contains("const KEY_NAME = 'allen.key';"));
        let uses: Vec<&str> = script.match_indices("localStorage").map(|(i, _)| &script[i..]).collect();
        assert_eq!(uses.len(), 3, "localStorage appears only in storedKey, keepKey and dropKey");
        for (call, n) in [("localStorage.getItem(KEY_NAME)", 1), ("localStorage.setItem(KEY_NAME, value)", 1), ("localStorage.removeItem(KEY_NAME)", 1)] {
            assert_eq!(script.matches(call).count(), n, "{call}");
        }
        assert_eq!(script.matches("keepKey(").count(), 3, "keepKey is defined once and called only on the consent path");
        // The gateway prepends the same bytes for each kind of start.
        assert!(script.contains(&format!("const GREETING_REMEMBER = \"{GREETING_REMEMBER}\";")));
        assert!(script.contains(&format!("const GREETING_ANONYMOUS = \"{GREETING_ANONYMOUS}\";")));
        assert!(script.contains("const BACK_LINE = '(I am back.)';"));
    }

    #[test]
    fn anonymous_is_the_default_and_never_sends_a_key() {
        let script = include_str!("../../../../public/js/allen.js");
        assert!(SKELETON.contains("id=\"allen\" data-ready=\"false\" data-busy=\"false\" data-mode=\"anonymous\""));
        assert!(SKELETON.contains("Anonymous: Allen won&#39;t remember this chat"));
        assert!(script.contains("  let remembered = false;\n"), "the script starts anonymous");
        // Remembered only on the consent path: after a consented save, after a
        // pasted key under the same consent box, or a key kept from an
        // earlier opt-in (unless the page was opened with ?mode=anonymous).
        assert_eq!(script.matches("remembered = true;").count(), 2);
        assert!(function_body(script, "saveIntro").contains("keepKey(reply.key)"));
        let card = function_body(script, "introCard");
        let gate = card.find("if (!agree.checked) return;").expect("the pasted key waits for consent");
        assert!(gate < card.find("keepKey(value)").expect("pasted key"), "consent is checked before the key is kept");
        assert!(script.contains("  if (entry === 'anonymous') goAnonymous(true);\n  else remembered = Boolean(storedKey());\n"));
        assert!(script.contains("const entry = new URLSearchParams(location.search).get('mode');"));
        let leave = function_body(script, "goAnonymous");
        assert!(leave.find("dropKey();").unwrap() < leave.find("remembered = false;").unwrap(), "the key leaves first");
        // Anonymous calls say so and carry no key; X-Allen-Key is written only
        // past that check and once in forgetOld, the explicit Forget me.
        let headers = function_body(script, "keyHeaders");
        let anonymous = headers.find("if (!remembered) return { 'X-Allen-Anonymous': '1' };").expect("anonymous branch first");
        assert!(anonymous < headers.find("'X-Allen-Key'").unwrap());
        assert_eq!(script.matches("'X-Allen-Key'").count(), 3);
        assert!(function_body(script, "forgetOld").contains("'X-Allen-Key': oldKey"));
    }

    #[test]
    fn the_page_interface_adds_no_powers() {
        // window.allen lets a page UI drive the chat, but keys are still kept
        // only on the consent path and programs still run where they did.
        let script = include_str!("../../../../public/js/allen.js");
        let start = script.find("  window.allen = Object.freeze({").expect("window.allen");
        let api = &script[start..start + script[start..].find("\n  });\n").expect("end of window.allen")];
        for banned in ["keepKey(", "localStorage", "INTRODUCE", "X-Allen-Key", "humanMessage(", "emit(", "innerHTML", "srcdoc"] {
            assert!(!api.contains(banned), "window.allen must not reach {banned}");
        }
        assert!(api.contains("rememberMe: () => {\n      if (!remembered) openIntro();"), "Remember me only opens the consent card");
        assert!(function_body(script, "emit").contains("Object.freeze({ ...detail })"));
    }

    #[test]
    fn the_root_says_its_mode_for_the_site_scripts() {
        // The site greeting and the X pixel loader read #allen's data-mode:
        // anonymous from the server, remembered only after consent or a key
        // from an earlier consent, kept in sync by showMode.
        let script = include_str!("../../../../public/js/allen.js");
        assert!(SKELETON.starts_with("<div class=\"allen\" id=\"allen\" data-ready=\"false\" data-busy=\"false\" data-mode=\"anonymous\">"));
        assert!(script.contains("const root = document.getElementById('allen');"));
        assert!(function_body(script, "showMode").contains("root.dataset.mode = remembered ? 'remembered' : 'anonymous';"));
        assert_eq!(script.matches("root.dataset.mode").count(), 1, "only showMode writes the mode");
        // The page UI binds on allen-ready, sent once window.allen exists.
        let api = script.find("  window.allen = Object.freeze({").unwrap();
        assert!(script.find("document.dispatchEvent(new Event('allen-ready'));").unwrap() > api);
        // The gateway is same origin unless a loopback base is configured.
        assert!(script.contains(r"const API = /^https?:\/\/(?:127\.0\.0\.1|localhost)(?::\d{1,5})?$/.test(configured) ? configured : '';"));
    }

    #[test]
    fn only_allen_nodes_carry_the_allen_speaker_mark() {
        let script = include_str!("../../../../public/js/allen.js");
        assert!(function_body(script, "message").contains("if (role === 'allen') item.dataset.speaker = 'allen';"));
        assert!(function_body(script, "greeting").contains("message('allen', 'Allen')"));
        assert_eq!(script.matches("dataset.speaker").count(), 1, "only message() marks a speaker");
        assert!(!function_body(script, "humanMessage").contains("speaker"));
        assert!(!SKELETON.contains("data-speaker"), "Drake's page copy is never marked as Allen's");
    }

    #[test]
    fn the_skeleton_declares_every_slot_the_script_fills() {
        for id in [
            "allen", "allen-log", "allen-form", "allen-input", "allen-send", "allen-stop", "allen-status", "allen-new",
            "allen-model", "allen-queue", "allen-ttft", "allen-first", "allen-rate", "allen-tokens", "allen-server", "allen-examples",
            "allen-key", "allen-key-body", "allen-introduce", "allen-drake", "allen-mode",
        ] {
            assert_eq!(SKELETON.matches(&format!(" id=\"{id}\"")).count(), 1, "exactly one #{id} in the skeleton");
        }
        assert!(SKELETON.contains("running on a DGX Spark in Drake's house"));
        assert!(SKELETON.contains("No prompts or IP addresses are logged."));
        assert!(!SKELETON.contains('\u{2014}') && !SKELETON.contains('\u{2013}'), "no em or en dash");
    }

    /// The body of the top-level function `name` in the generated script.
    fn function_body<'a>(script: &'a str, name: &str) -> &'a str {
        let start = script.find(&format!(" function {name}(")).unwrap_or_else(|| panic!("allen.js lacks function {name}"));
        let end = script[start..].find("\n  }\n").expect("function end") + start;
        &script[start..end]
    }

    #[test]
    fn only_the_session_channel_can_show_drake() {
        // The Drake name and avatar are made in exactly one function, and that
        // function is called only for `event: human` on the session stream,
        // which the gateway emits only for Drake's authenticated console.
        // Model tokens and visitor text go through message('allen'|'user').
        let script = include_str!("../../../../public/js/allen.js");
        let human = function_body(script, "humanMessage");
        for marker in ["'Drake'", "allen-msg-drake", "allen-avatar"] {
            assert_eq!(script.matches(marker).count(), 1, "{marker} must occur exactly once");
            assert!(human.contains(marker), "{marker} must be inside humanMessage");
        }
        assert_eq!(script.matches("humanMessage(").count(), 2, "humanMessage is defined once and called once");
        let session = function_body(script, "onSession");
        assert!(session.contains("if (name === 'human' && typeof value.text === 'string') {\n      humanMessage("));
        // The page UI hears Drake only through the same branch.
        assert_eq!(script.matches("emit('human'").count(), 1);
        assert!(session.contains("emit('human', { text: value.text.slice(0, 8000) });"));
        assert!(function_body(script, "session").contains("sse((name, data) => onSession(name, data, controller))"));
        assert_eq!(script.matches("onSession(").count(), 2, "onSession is fed only by the session stream");
        for (role, label) in [("user", "'You'"), ("allen", "'Allen'")] {
            assert!(script.contains(&format!("message('{role}', {label})")));
        }
        assert!(!script.contains("message('drake'"), "message() never takes a Drake role");
        assert_eq!(script.matches("message(role").count(), 1, "message(role, label) is only defined, never called with a variable role");
    }

    #[test]
    fn llms_documents_the_consent_gated_introduction_in_the_first_person_singular() {
        for needle in ["POST https://www.aienos.com/allen/api/introduce", "\"consent\": true", "\"human\"", "consent_required", "#forget=", "aien@aienos.com"] {
            assert!(LLMS.contains(needle), "llms.txt section lacks {needle}");
        }
        let script = include_str!("../../../../public/js/allen.js");
        // Drake's greetings are Allen speaking and keep his words; every other
        // string stays first person singular.
        let script = script.replace(GREETING_REMEMBER, "").replace(GREETING_ANONYMOUS, "");
        for text in [LLMS, SKELETON, script.as_str()] {
            assert!(!text.contains('\u{2014}') && !text.contains('\u{2013}'), "no em or en dash");
            for word in text.split(|c: char| !c.is_ascii_alphabetic()) {
                let w = word.to_ascii_lowercase();
                assert!(!["we", "us", "our", "ours", "ourselves"].contains(&w.as_str()), "plural first person: {word}");
            }
        }
    }

    #[test]
    fn the_stylesheet_stays_on_the_shared_palette_and_compositor_motion() {
        let css = include_str!("../../../../public/assets/allen.css");
        assert!(!css.contains("@import") && !css.contains("url("), "allen.css loads nothing from outside");
        assert!(!css.contains('#'), "allen.css takes its colours from the style.css tokens, not hex literals");
        for line in css.lines().filter(|l| l.contains("transition") || l.contains("animation")) {
            assert!(!line.contains("filter") && !line.contains("box-shadow") && !line.contains("transition: all"), "compositor-only motion: {line}");
        }
    }
}
